"""Reference rates published by the treasury rate service."""

import json
import re
import urllib.request
from dataclasses import dataclass
from decimal import Decimal

RATES_URL = "https://fx.treasury.internal/v1/rates"


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        raise RateError("invalid JSON")

    if not isinstance(data, dict):
        raise RateError("payload must be an object")

    if "base" not in data:
        raise RateError("missing base currency")

    base = data["base"]
    if not isinstance(base, str):
        raise RateError("base must be a string")

    if not re.fullmatch(r"[A-Z]{3}", base):
        raise RateError("base must be three uppercase letters")

    if "as_of" not in data:
        raise RateError("missing as_of timestamp")

    as_of = data["as_of"]
    if not isinstance(as_of, str):
        raise RateError("as_of must be a string")

    if "rates" not in data:
        raise RateError("missing rates object")

    rates_data = data["rates"]
    if not isinstance(rates_data, dict):
        raise RateError("rates must be an object")

    rates = {}
    for currency, rate_str in rates_data.items():
        if not isinstance(currency, str) or not re.fullmatch(r"[A-Z]{3}", currency):
            raise RateError("currency codes must be three uppercase letters")

        if not isinstance(rate_str, str):
            raise RateError("rates must be decimal strings")

        try:
            rate_value = Decimal(rate_str)
        except:
            raise RateError("rates must be valid decimals")

        if not (rate_value > 0 and rate_value.is_finite()):
            raise RateError("rates must be positive and finite")

        rates[currency] = rate_value

    # Ensure base currency is always present with rate 1
    rates[base] = Decimal(1)

    return RateTable(base=base, as_of=as_of, rates=rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    if not isinstance(base, str) or not re.fullmatch(r"[A-Z]{3}", base):
        raise RateError("base must be three uppercase letters")

    url = f"{RATES_URL}?base={base}"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:
            if response.status != 200:
                raise RateError(f"rate service unavailable: {response.status}")
            body = response.read().decode()
    except Exception as e:
        raise RateError(f"rate service unavailable: {str(e)}")

    return parse_rates(body)
